(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const icons={arrow:'M5 12h14m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',file:'M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M4 21v-3a8 5 0 0 1 16 0v3'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.arrow}"/></svg>`;
let toastTimer;function toast(text){const t=$('#toast');if(!t)return;t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3500)}
function download(name,text){const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Le fichier a été préparé pour le téléchargement.')}
function tabs(selector,callback){const buttons=$$(selector);buttons.forEach((b,i)=>{b.addEventListener('click',()=>{buttons.forEach(x=>{x.setAttribute('aria-selected',String(x===b));x.tabIndex=x===b?0:-1});const p=document.getElementById(b.getAttribute('aria-controls'));if(p)p.setAttribute('aria-labelledby',b.id);callback(i)});b.addEventListener('keydown',e=>{let j;if(e.key==='ArrowRight'||e.key==='ArrowDown')j=(i+1)%buttons.length;if(e.key==='ArrowLeft'||e.key==='ArrowUp')j=(i+buttons.length-1)%buttons.length;if(e.key==='Home')j=0;if(e.key==='End')j=buttons.length-1;if(j!==undefined){e.preventDefault();buttons[j].focus();buttons[j].click()}})})}
const menu=$('.menu-toggle');if(menu){const nav=$('#main-nav');function close(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Ouvrir le menu');nav.classList.remove('is-open')}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Ouvrir le menu':'Fermer le menu');nav.classList.toggle('is-open',!open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('is-open')){close();menu.focus()}})}
if($('[data-trace]')){const original=$('.story-art').innerHTML;const stages=[{label:'01 / Collecter',title:'La donnée garde son contexte.',text:'Une consommation reste liée à sa pièce, à son site et à sa période. Rien ne se perd entre le terrain et le résultat.',art:original},{label:'02 / Calculer',title:'Un résultat que l’on peut expliquer.',text:'La quantité, le facteur et la conversion restent visibles. Vous comprenez comment un relevé devient une estimation d’émissions.',art:`<div class="visual-calculation"><span class="eyebrow">Électricité · Janvier 2025</span><div class="calc-big">5 <small>tCO₂e</small></div><div class="calc-rule">10 000 kWh × 0,5 kgCO₂e/kWh ÷ 1 000<br>Facteur fictif, utilisé pour cette démonstration.</div></div>`},{label:'03 / Examiner',title:'Une revue qui laisse une trace.',text:'Vérifier une période, examiner une quantité, discuter un facteur : chaque étape aide l’équipe à comprendre le chiffre.',art:`<div class="visual-review"><span class="eyebrow">Revue de la donnée</span><h3>Les bons points de contrôle.</h3><p>${icon('check')}Pièce et période associées</p><p>${icon('check')}Unité de consommation explicite</p><p>${icon('clock')}Facteur à confirmer</p><small>Exemple d’une revue interne, sans certification.</small></div>`},{label:'04 / Décider',title:'Savoir où regarder ensuite.',text:'Le résultat sert à prioriser les investigations. Chaque piste reste rattachée aux observations, aux responsables et aux limites des données.',art:`<div class="visual-decision"><span class="eyebrow">Une piste à explorer</span><h3>Comprendre le pic de juillet.</h3><p>Comparer les usages énergétiques et la production avant d’estimer une réduction.</p><span class="status attention" style="margin-top:22px">À étudier avec l’exploitation</span></div>`}];tabs('[data-trace]',i=>{const x=stages[i];$('.story-art').innerHTML=x.art;$('.story-explanation').innerHTML=`<span class="step-label">${x.label}</span><h3>${x.title}</h3><p>${x.text}</p><a href="preuves.html">Explorer une preuve ${icon('arrow')}</a>`})}
if($('[data-workflow]')){const content=$('.workflow-content'),collect=content.innerHTML;const link=(t,u)=>`<a class="button outline" href="${u}">${t}${icon('arrow')}</a>`;const panels=[`<div class="panel-title"><div><h3>Donner un cadre à la démarche.</h3><p>Une campagne, un site et des sources explicites.</p></div><span class="pill">01 · Cadrage</span></div><ul class="workflow-steps"><li>${icon('check')}Exercice 2025 · Site d’El Jadida</li><li>${icon('check')}Électricité achetée et carburants illustrés</li><li>${icon('clock')}Autres sources à examiner avec l’équipe</li></ul><p class="quiet">Le périmètre de cet exemple est volontairement partiel.</p>`,collect,`<div class="panel-title"><div><h3>Remonter jusqu’à la pièce.</h3><p>Trois exemples pour explorer le détail du calcul.</p></div><span class="pill">03 · Revue</span></div><ul class="workflow-steps"><li>${icon('file')}Électricité · Janvier 2025</li><li>${icon('file')}Électricité · Février 2025</li><li>${icon('file')}Carburant · Janvier 2025</li></ul>${link('Ouvrir les données et preuves','preuves.html')}`,`<div class="panel-title"><div><h3>Comprendre la répartition.</h3><p>Un total relié à ses sources et à ses limites.</p></div><span class="pill">04 · Lecture</span></div><div class="workflow-metrics"><div><span>Électricité</span><strong>60 tCO₂e</strong><p>Source illustrative · Scope 2</p></div><div><span>Carburants</span><strong>40 tCO₂e</strong><p>Source illustrative · Scope 1</p></div></div><p class="quiet">100 tCO₂e au total dans cet exemple. Les autres sources ne sont pas comptabilisées.</p>${link('Lire l’année dans l’espace client','espace.html')}`,`<div class="panel-title"><div><h3>Faire du résultat un point de départ.</h3><p>Des investigations concrètes, attribuées à une équipe.</p></div><span class="pill">05 · Actions</span></div><ul class="workflow-steps"><li>${icon('user')}Exploitation · Comprendre le pic de juillet</li><li>${icon('user')}Maintenance · Examiner les usages à l’arrêt</li><li>${icon('user')}Achats · Compléter les données fournisseurs</li></ul>${link('Explorer le plan d’action','espace.html?view=actions')}`];tabs('[data-workflow]',i=>content.innerHTML=panels[i])}
if($('#records')){const records=[{title:'Électricité · Janvier',period:'Janvier 2025',file:'electricite-janvier.pdf',quantity:10000,unit:'kWh',factor:.5,total:5,dates:'01/01 — 31/01/2025',kind:'Électricité',scope:'Scope 2 · Électricité'},{title:'Électricité · Février',period:'Février 2025',file:'electricite-fevrier.pdf',quantity:7500,unit:'kWh',factor:.5,total:3.75,dates:'01/02 — 28/02/2025',kind:'Électricité',scope:'Scope 2 · Électricité'},{title:'Carburant · Janvier',period:'Janvier 2025',file:'carburant-janvier.pdf',quantity:800,unit:'L',factor:2.5,total:2,dates:'01/01 — 31/01/2025',kind:'Carburant',scope:'Scope 1 · Carburant'}];let selected=Math.min(2,Math.max(0,(Number(new URLSearchParams(location.search).get('record'))||1)-1));const reviewed=new Set();const num=n=>n.toLocaleString('fr-FR');function renderList(){const query=$('#record-search').value.toLocaleLowerCase('fr');$('#records').innerHTML=records.map((r,i)=>({r,i})).filter(({r})=>(r.title+' '+r.period+' '+r.file).toLocaleLowerCase('fr').includes(query)).map(({r,i})=>`<button class="record-button" data-record="${i}" aria-pressed="${selected===i}">${icon(reviewed.has(i)?'check':'file')}<span><strong>${r.title}</strong><small>${reviewed.has(i)?'Revue effectuée':'À examiner'} · ${num(r.total)} tCO₂e</small></span></button>`).join('')||'<p class="record-empty">Aucune pièce ne correspond à cette recherche.</p>'}function renderDetail(){const r=records[selected];$('#document-name').textContent=r.file;$('#invoice-period').textContent=r.period;$('#invoice-quantity').innerHTML=`${num(r.quantity)} <small>${r.unit}</small>`;$('#invoice-dates').textContent=r.dates;$('.invoice-tag').textContent=r.kind;$('.invoice-highlight>span').textContent=r.kind==='Carburant'?'Carburant consommé':'Énergie consommée';$('#proof-scope').textContent=r.scope;$('#proof-total').textContent=num(r.total);$('#proof-quantity').textContent=`${num(r.quantity)} ${r.unit}`;$('#proof-factor').textContent=`${num(r.factor)} kgCO₂e/${r.unit}`;$('#calculation-trail').textContent=`${num(r.quantity)} ${r.unit} × ${num(r.factor)} kgCO₂e/${r.unit} ÷ 1 000 = ${num(r.total)} tCO₂e. Facteur fictif. Les documents présentés sont des exemples et ne couvrent pas l’ensemble du total annuel.`;const done=reviewed.has(selected);$('#review-status').innerHTML=icon(done?'check':'clock')+(done?'Revue interne marquée':'Pièce à examiner');$('#review-status').classList.toggle('reviewed',done);$('#review-record').innerHTML=(done?'Pièce marquée comme revue':'Marquer comme revue')+icon('check');$('#review-record').disabled=done;$('#undo-review').hidden=!done}$('#record-search').addEventListener('input',renderList);$('#records').addEventListener('click',e=>{const b=e.target.closest('[data-record]');if(b){selected=Number(b.dataset.record);renderList();renderDetail()}});$('#review-record').addEventListener('click',()=>{reviewed.add(selected);renderList();renderDetail();toast('Revue marquée pour cet exemple. Vous pouvez l’annuler.')});$('#undo-review').addEventListener('click',()=>{reviewed.delete(selected);renderList();renderDetail();$('#review-record').focus();toast('La pièce est de nouveau à examiner.')});renderList();renderDetail()}
if($('#package-panel')){const options=[{title:'Construire une première base solide.',text:'Commencer par un périmètre compris de tous, organiser la collecte, puis restituer les résultats et leurs limites.',items:['Atelier de cadrage et responsabilités','Collecte structurée avec pièces justificatives','Calculs expliqués et hypothèses documentées','Restitution et pistes de travail prioritaires']},{title:'Répondre avec un dossier clair.',text:'Partir de la demande reçue pour définir les informations utiles, les données disponibles et les éléments à compléter.',items:['Lecture de la demande de votre client','Liste des données et des preuves attendues','Dossier adapté au format demandé','Revue des limites avant transmission']},{title:'Préparer les données avant l’échéance.',text:'Identifier vos produits et vos flux, préciser le cadre applicable avec les interlocuteurs compétents et structurer les informations à produire.',items:['Cadrage des produits et des sites concernés','Identification des données de production','Organisation des preuves et des responsables','Dossier de travail et points à faire confirmer']}];function render(i){const o=options[i];$('#package-panel').innerHTML=`<div><h3>${o.title}</h3><p>${o.text}</p><button class="text-link" data-open-brief>Préparer mon échange ${icon('arrow')}</button></div><ul class="deliverables">${o.items.map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul>`}tabs('[data-package]',render);render(0);const dialog=$('#brief-dialog');let opener;document.addEventListener('click',e=>{const button=e.target.closest('[data-open-brief]');if(button){opener=button;dialog.showModal()}if(e.target.closest('[data-close-dialog]'))dialog.close()});dialog.addEventListener('close',()=>opener?.focus());const form=$('#brief-form');form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);$('#brief-text').textContent=`BRIEF DE PREMIER ÉCHANGE — SPS-CARBON\n\nActivité : ${d.get('activity')}\nNombre de sites : ${d.get('sites')}\nBesoin : ${d.get('need')}\n\nPriorité\n${d.get('priority')}\n\nPréparé localement dans le prototype Atelier Carbone.\nAucune information transmise. Ce document n’est pas une offre commerciale.`;form.hidden=true;$('#brief-result').hidden=false;$('#download-brief').focus()});$('#edit-brief').addEventListener('click',()=>{form.hidden=false;$('#brief-result').hidden=true;form.elements.activity.focus()});$('#download-brief').addEventListener('click',()=>download('SPS-CARBON-mon-brief.txt',$('#brief-text').textContent))}
if($('.workspace-shell')){const views=['overview','collecte','actions'];function view(v,focus=false){if(!views.includes(v))v='overview';$$('.workspace-view').forEach(x=>x.hidden=x.id!=='view-'+v);$$('.workspace-sidebar [data-view]').forEach(x=>{if(x.dataset.view===v)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});if(focus){const section=$('#view-'+v);section.tabIndex=-1;section.focus({preventScroll:true})}}$$('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view,true)));view(new URLSearchParams(location.search).get('view')||'overview');const taskData=[{title:'Matières premières',description:'Quantités achetées et pièces fournisseurs · Exercice 2025',owner:'Équipe achats',done:false},{title:'Emballages',description:'Volumes et composition des emballages achetés · Exercice 2025',owner:'Équipe achats',done:false},{title:'Transport amont',description:'Trajets et données des prestataires · Exercice 2025',owner:'Logistique',done:false}];function renderTasks(){const filter=$('#task-filter').value;$('#collection-tasks').innerHTML=taskData.map((t,i)=>({t,i})).filter(({t})=>filter==='all'||filter==='done'&&t.done||filter==='pending'&&!t.done).map(({t,i})=>`<article class="collection-task"><div><span class="status ${t.done?'good':'attention'}">${t.done?'Pièce reçue — exemple':'À recevoir'}</span><h3>${t.title}</h3><p>${t.description}</p></div><div class="task-controls"><label>Responsable<select class="task-owner" data-owner="${i}" aria-label="Responsable pour ${t.title}">${['Équipe achats','Logistique','Exploitation'].map(o=>`<option ${t.owner===o?'selected':''}>${o}</option>`).join('')}</select></label><button class="button outline" data-task="${i}">${t.done?'Annuler la réception':'Simuler une pièce reçue'} ${icon(t.done?'clock':'check')}</button></div></article>`).join('')||'<p class="quiet">Aucune demande dans cette catégorie.</p>';const done=taskData.filter(t=>t.done).length,left=3-done;$('.nav-count').textContent=String(left);$('.collection-summary>strong').innerHTML=`${24+done}<small>/ 27</small>`;$('.collection-summary>p').innerHTML=`${left?`${left} document${left>1?'s':''} d’achats attendu${left>1?'s':''}.`:'Pièces marquées comme reçues dans la démonstration.'}<br>La collecte ne mesure pas la couverture des émissions.`;$('.workspace-bottom>div:first-child>p').textContent=left?`${left} demande${left>1?'s attendent':' attend'} les données de l’équipe achats.`:'Les pièces de démonstration ont été marquées comme reçues.'}$('#task-filter').addEventListener('change',renderTasks);$('#collection-tasks').addEventListener('change',e=>{if(e.target.matches('[data-owner]')){taskData[Number(e.target.dataset.owner)].owner=e.target.value;toast('Responsable modifié dans cette démonstration.')}});$('#collection-tasks').addEventListener('click',e=>{const b=e.target.closest('[data-task]');if(b){const t=taskData[Number(b.dataset.task)];t.done=!t.done;renderTasks();toast(t.done?'Réception simulée. Aucun fichier n’a été envoyé.':'Réception annulée.');const next=$(`[data-task="${b.dataset.task}"]`);if(next)next.focus();else $('#task-filter').focus()}});$$('[data-action-done]').forEach(b=>{const a=b.closest('article'),status=$('.status',a),initial=status.textContent;b.addEventListener('click',()=>{const done=a.classList.toggle('is-done');status.textContent=done?'Étudié — exemple':initial;status.classList.toggle('good',done);b.innerHTML=(done?'Rouvrir l’investigation':'Marquer comme étudié')+icon(done?'clock':'check');toast(done?'Investigation marquée comme étudiée.':'Investigation rouverte.')})});$('#export-workspace').addEventListener('click',()=>download('SPS-CARBON-synthese-demonstration.txt',`SPS-CARBON — ATELIER ATLAS\nSYNTHÈSE DE DÉMONSTRATION — DONNÉES FICTIVES\n\nExercice : 2025\nPérimètre illustré : électricité et carburants\nTotal annuel illustratif : 100 tCO₂e\nÉlectricité : 60 tCO₂e\nCarburants : 40 tCO₂e\n\nMois (tCO₂e)\nJanvier 7 ; Février 6,25 ; Mars 8,5 ; Avril 7,75 ; Mai 8,75 ; Juin 9 ; Juillet 10 ; Août 8,75 ; Septembre 8,5 ; Octobre 8,5 ; Novembre 9 ; Décembre 8.\n\nExemples de calcul\nÉlectricité janvier : 10 000 kWh × 0,5 kgCO₂e/kWh ÷ 1 000 = 5 tCO₂e.\nÉlectricité février : 7 500 kWh × 0,5 kgCO₂e/kWh ÷ 1 000 = 3,75 tCO₂e.\nCarburant janvier : 800 L × 2,5 kgCO₂e/L ÷ 1 000 = 2 tCO₂e.\nLes pièces affichées sont des extraits de la série annuelle, pas un relevé exhaustif.\n\nCollecte dans cette page : ${24+taskData.filter(t=>t.done).length}/27 pièces.\nAutres sources d’émissions : non calculées dans cette démonstration.\nLa collecte ne mesure pas la couverture des émissions.\n\nFacteurs fictifs. Aucune valeur réglementaire. Aucune certification ni réduction d’émissions attestée.\nPrototype de design, sans connexion à des données réelles.`));renderTasks()}
})();
